package android.graphics;import java.io.*;import javax.imageio.ImageIO;import android.graphics.drawable.*;public class ImageDecoder {public static final int ALLOCATOR_SOFTWARE=1;public record Source(File file){}public record Size(int width,int height){public int getWidth(){return width;}public int getHeight(){return height;}}public record ImageInfo(Size size){public Size getSize(){return size;}}public interface Listener {void configure(ImageDecoder d,ImageInfo i,Source s);}public static Source createSource(File f){return new Source(f);}public void setAllocator(int n){}public void setTargetSampleSize(int n){}public void setTargetSize(int w,int h){}public static Bitmap decodeBitmap(Source source,Listener l)throws IOException{java.awt.image.BufferedImage image=ImageIO.read(source.file());if(image==null)throw new IOException("not image");l.configure(new ImageDecoder(),new ImageInfo(new Size(image.getWidth(),image.getHeight())),source);return new Bitmap(image);}public static Drawable decodeDrawable(Source source,Listener l)throws IOException{decodeBitmap(source,l);try(InputStream in=new FileInputStream(source.file())){byte[] b=in.readNBytes(6);return new String(b).startsWith("GIF")?new AnimatedImageDrawable():new Drawable();}}}